## 2. Código Webhook em Node.js

```javascript
// server.js
const express = require('express');
const bodyParser = require('body-parser');

const app = express();
app.use(bodyParser.json());

// Mapeamento de respostas
const respostas = {
    saudacao: "Olá! Eu sou o assistente virtual. Como posso ajudar você hoje?",
    precos: "Nossos serviços começam a partir de R$ 50,00. Você gostaria de saber mais detalhes sobre algum serviço específico?",
    horario: "Estamos abertos de segunda a sexta das 9h às 18h. No fim de semana das 10h às 14h.",
    obrigado: "De nada! Se precisar de mais alguma ajuda, é só chamar.",
    help: "Posso ajudá-lo com: 1) Preços dos serviços 2) Horário de funcionamento 3) Outras dúvidas"
};

// Rota para o webhook do Dialogflow
app.post('/webhook', (req, res) => {
    const intent = req.body.queryResult.intent.displayName;
    let resposta = "";

    switch (intent) {
        case 'saudacao':
            resposta = respostas.saudacao;
            break;
        case 'precos':
            resposta = respostas.precos;
            break;
        case 'horario':
            resposta = respostas.horario;
            break;
        case 'obrigado':
            resposta = respostas.obrigado;
            break;
        case 'help':
            resposta = respostas.help;
            break;
        default:
            resposta = "Desculpe, não entendi sua pergunta. Pode reformular?";
    }

    // Resposta do webhook
    res.json({
        fulfillmentText: resposta,
        // Para manter o contexto da conversa
        context: [
            {
                name: 'saudacao',
                lifespan: 2
            }
        ]
    });
});

// Iniciar o servidor
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Servidor do webhook rodando na porta ${PORT}`);
});
```

